import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.CdTmk4Xw.js";const g=JSON.parse('{"title":"Contributing","description":"","frontmatter":{"editLink":true},"headers":[],"relativePath":"contributing.md","filePath":"contributing.md"}'),n={name:"contributing.md"};function o(r,e,c,d,h,l){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>Read the <a href="https://github.com/xw7qwq/.github/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">organization contribution guide</a>. Choose the target branch before editing: <code>main</code> for algorithms, <code>docs/project-guide</code> for documentation, or <code>gh-pages</code> for the website. See <a href="./maintenance.html">Maintenance</a> for branch responsibilities and synchronization.</p><h2 id="make-a-change" tabindex="-1">Make a change <a class="header-anchor" href="#make-a-change" aria-label="Permalink to &quot;Make a change&quot;">​</a></h2><ol><li>Check <code>git status --short --branch</code> and preserve existing uncommitted work.</li><li>Create a clearly named branch from the relevant baseline, such as <code>fix/cf-1000-e</code> or <code>docs/update-tooling</code>.</li><li>Follow the <a href="./conventions.html">code and archive conventions</a>, keeping each commit focused on one purpose.</li><li>Track new files by path, complete the applicable checks below, and review the staged diff.</li><li>Explain the reason and validation scope, push the working branch, and open a PR against its target. Merge after checks pass.</li><li>Confirm the target contains the changes before deleting the temporary branch. Keep the three permanent branches: <code>main</code>, <code>docs/project-guide</code>, and <code>gh-pages</code>.</li></ol><table tabindex="0"><thead><tr><th>Change</th><th>Evidence before submission</th></tr></thead><tbody><tr><td>Individual algorithm</td><td>Compile independently and record sample, boundary, and counterexample results; an AC claim requires an online judge record</td></tr><tr><td>Template</td><td>Provide a minimal caller and boundary checks; explain interface changes</td></tr><tr><td>Rename or move</td><td>Preserve traceable source mappings and check CPH path rules and Pages inclusion rules</td></tr><tr><td>Archive tools or imported source</td><td>Run offline archive tests and the read-only provenance audit below</td></tr><tr><td>Documentation</td><td>Run documentation checks, API contract checks, and a build; see <a href="./maintenance.html">Maintenance</a></td></tr><tr><td>Website</td><td>Validate assets, snapshots, and affected interactions using <a href="./pages.html">website maintenance</a></td></tr></tbody></table><p>If the source branch does not yet include documentation checks, run the relevant checks available on that branch and update documentation separately on its branch. Run archive tests and the integrity audit from the repository root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unittest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/tests</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;test_archive_*.py&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/archive_verify.py</span></span></code></pre></div><p>The <code>archive</code> check verifies tool behavior and source integrity where provenance receipts exist. It does not execute algorithms or establish an AC verdict. Archive tools read and write local files without committing or pushing Git. New sources enter <code>main</code> through a temporary branch such as <code>sync/</code> and a PR, preserving existing source files. See the <a href="https://github.com/xw7qwq/codeflare/blob/docs/project-guide/scripts/README.md" target="_blank" rel="noreferrer">archive tool guide</a> for operations and receipt formats.</p><p>All manual changes require PRs. The documentation publishing workflow writes directly to the generated <code>gh-pages/docs/</code> directory. The <code>Site snapshots</code> workflow on <code>main</code> writes only the generated <code>gh-pages/data/site-data.json</code> and <code>gh-pages/data/recent-commits.json</code> after main pushes, daily, or on manual runs; PR runs only validate. Both publishers share a lock and preserve pending jobs with <code>queue: max</code>. Do not edit generated output manually. Keep the full <code>gh-pages</code> branch separate from other branches.</p><h2 id="commit-messages" tabindex="-1">Commit messages <a class="header-anchor" href="#commit-messages" aria-label="Permalink to &quot;Commit messages&quot;">​</a></h2><p>Use English and the format <code>type(scope): specific action</code>, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fix(codeforces): handle disconnected graph in 1000E</span></span>
<span class="line"><span>feat(atcoder): add abc231 A solution</span></span>
<span class="line"><span>docs(tooling): explain local relay configuration</span></span>
<span class="line"><span>refactor(layout): move verified source paths</span></span></code></pre></div><p>Common types are <code>feat</code>, <code>fix</code>, <code>refactor</code>, <code>docs</code>, and <code>chore</code>. Include necessary motivation, provenance, and test results in the body. Successful compilation alone does not mean all tests passed.</p><p>Stage and review files individually. For a README-only change:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> README.md</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cached</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cached</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;docs(readme): clarify repository navigation&quot;</span></span></code></pre></div><h2 id="review-notes" tabindex="-1">Review notes <a class="header-anchor" href="#review-notes" aria-label="Permalink to &quot;Review notes&quot;">​</a></h2><p>Provide the following information, keeping simple changes brief:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Reason: The previous behavior or missing information.</span></span>
<span class="line"><span>Change: The files changed and resulting behavior.</span></span>
<span class="line"><span>Validation: Commands or examples actually run, and their results.</span></span>
<span class="line"><span>Limitations: Any scope not yet verified; omit when unnecessary.</span></span></code></pre></div><p>For algorithm discussions, provide the problem link, a minimal counterexample, and expected output. Retain attribution and applicable licenses for third-party code. The repository has no single declared license; do not invent permissions for existing code.</p>`,19)])])}const u=a(n,[["render",o]]);export{g as __pageData,u as default};
